if (Get-Command winget -ErrorAction SilentlyContinue) {
    Write-Host "✔ Winget Package Manager is available!"
} else {
    Write-Host "Winget is not installed."
}

Write-Host "=== 02: Object Pipelines ==="
$topProcesses = Get-Process | Sort-Object -Property WorkingSet64 -Descending | Select-Object -First 3 -Property ProcessName, @{Name='RAM (MB)'; Expression={[math]::Round($_.WorkingSet64 / 1MB, 2)}}
$topProcesses | Format-Table -AutoSize

$item = Get-Item $env:TEMP
if ($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
    Write-Host "$($item.FullName) is a Reparse Point (Junction/Symlink)"
} else {
    Write-Host "$($item.FullName) is a standard directory."
}

$testPath = "HKCU:\Software\Microsoft\Windows"
if (Test-Path $testPath) {
    Write-Host "✔ Registry key exists: $testPath"
} else {
    Write-Host "Key does not exist."
}

$privs = whoami /priv
if ($privs -match 'SeShutdownPrivilege') {
    Write-Host "✔ SeShutdownPrivilege present in token."
}

Write-Host "=== 12: WSL Distribution Status ==="
if (Get-Command wsl -ErrorAction SilentlyContinue) {
    wsl --list --verbose
} else {
    Write-Host "WSL not installed."
}

if (Get-Command wsl -ErrorAction SilentlyContinue) {
    wsl --status
}

# 15 — Production PowerShell Scripting & Modules

## 🎯 Advanced Function Template
```powershell
function Invoke-CustomTask {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$TargetHost
    )
    $ErrorActionPreference = 'Stop'
    try {
        Write-Verbose "Connecting to $TargetHost..."
    } catch {
        Write-Error $_.Exception.Message
    }
}
```

function Get-TrakGreeting {
    [CmdletBinding()]
    param(
        [string]$Name = "User"
    )
    [PSCustomObject]@{
        Timestamp = (Get-Date)
        Message   = "Welcome to Trak, $Name!"
    }
}

Write-Host "=== 15: Advanced Function Output ==="
Get-TrakGreeting -Name "ndk123-web" | Format-List

function Deploy-Target {
    [CmdletBinding()]
    param(
        [ValidateSet('prod', 'stage', 'dev')]
        [string]$Environment
    )
    Write-Host "Deploying to environment: $Environment"
}
Deploy-Target -Environment 'prod'

Write-Host "=== 16: Installed Software via Registry ==="
$uninstallKeys = @(
    "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall",
    "HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall"
)
$apps = foreach ($key in $uninstallKeys) {
    if (Test-Path $key) {
        Get-ItemProperty "$key\*" | Where-Object DisplayName | Select-Object -First 3 -Property DisplayName, DisplayVersion
    }
}
$apps | Format-Table -AutoSize

# 17 — Pester Testing Framework for PowerShell

## 🎯 Pester BDD Syntax
```powershell
Describe 'Math Utilities' {
    It 'Adds numbers correctly' {
        (2 + 3) | Should -Be 5
    }
}
```

Write-Host "=== 17: Self-Contained Test Assertion ==="
function Add-Numbers($a, $b) { $a + $b }

if ((Add-Numbers 4 6) -eq 10) {
    Write-Host "✔ [PASS] Add-Numbers test verified successfully!"
} else {
    throw "Test Failed!"
}

function Reverse-String($s) {
    $chars = $s.ToCharArray()
    [Array]::Reverse($chars)
    -join $chars
}

if ((Reverse-String 'powershell') -eq 'llehsrewop') {
    Write-Host "✔ [PASS] Reverse-String test passed!"
}
